import{_ as e,c as o,o as n,a9 as i}from"./chunks/framework.C3PHgg-M.js";const m=JSON.parse('{"title":"Exposing Commands","description":"Learn how to call commands as REST-API or via GraphQL","frontmatter":{"title":"Exposing Commands","description":"Learn how to call commands as REST-API or via GraphQL","order":207000},"headers":[],"relativePath":"handbook/2_building_business-logic/exposing_endpoints/index.md","filePath":"handbook/2_building_business-logic/exposing_endpoints/index.md","lastUpdated":1770405599000}'),s={name:"handbook/2_building_business-logic/exposing_endpoints/index.md"};function r(t,a,d,l,p,c){return n(),o("div",null,[...a[0]||(a[0]=[i('<h1 id="exposing-commands" tabindex="-1">Exposing Commands <a class="header-anchor" href="#exposing-commands" aria-label="Permalink to “Exposing Commands”">​</a></h1><p>PURISTA commands are transport-agnostic by design.<br> Business logic is implemented in commands once, and exposed through one or more adapters.</p><h2 id="available-approaches" tabindex="-1">Available approaches <a class="header-anchor" href="#available-approaches" aria-label="Permalink to “Available approaches”">​</a></h2><ul><li><a href="./rest_api_http_endpoints.html">REST API</a>: use <code>@purista/hono-http-server</code> for HTTP/OpenAPI.</li><li><a href="./graphql_mutation_and_query.html">GraphQL</a>: build a GraphQL layer that invokes commands.</li></ul><h2 id="which-approach-to-choose" tabindex="-1">Which approach to choose <a class="header-anchor" href="#which-approach-to-choose" aria-label="Permalink to “Which approach to choose”">​</a></h2><ul><li>Use REST when you want standardized HTTP semantics, generated OpenAPI, and broad tooling support.</li><li>Use GraphQL when clients need flexible selection of fields and a single typed query endpoint.</li><li>You can use both in parallel because commands stay independent from protocol-specific code.</li></ul><h2 id="design-guideline" tabindex="-1">Design guideline <a class="header-anchor" href="#design-guideline" aria-label="Permalink to “Design guideline”">​</a></h2><p>Keep command contracts schema-driven and stable. Adapters (REST/GraphQL) should only map incoming requests to command payload/parameter and map command output back to transport-specific responses.</p>',8)])])}const u=e(s,[["render",r]]);export{m as __pageData,u as default};
